@code {
    private string trackingNumber = string.Empty;
    private Shipment? shipment;
    private bool isLoading;
    private bool notFound;

    private async Task HandleKeyUp(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await TrackShipment();
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        isLoading = true;
        notFound = false;
        shipment = null;
        try
        {
            shipment = await ShipmentService.TrackShipmentAsync(trackingNumber.Trim());
            notFound = shipment is null;
        }
        finally
        {
            isLoading = false;
        }
    }

    private string GetStatusColor(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "success",
        ShipmentStatus.InTransit => "info",
        ShipmentStatus.OutForDelivery => "primary",
        ShipmentStatus.Delayed => "danger",
        ShipmentStatus.PickedUp => "secondary",
        _ => "warning"
    };
}
